  if(!Z.mock&&Z.pick!=null)h+='<div class="fb '+(Z.pick===q[3]?'ok':'bad')+'">'+(Z.pick===q[3]?'Right. ':'Not quite. ')+esc(q[4])+'</div><button class="btn" onclick="AV.pr.i++;AV.pr.pick=null;render();window.scrollTo(0,0)">Next</button>';
