window.ashPick=function(i){var Z=AV.pr,k=Z.q[Z.i],D=A();if(Z.mock){Z.ans[k]=i;render();return}if(Z.pick!=null)return;Z.pick=i;var ok=i===AQ[k][3];if(ok)Z.r++;D.st[k]=ok?1:0;save();render()};
window.ashEnd=function(){var Z=AV.pr,D=A();xStop();if(Z.done)return;Z.done=1;Z.t=Math.min(2700,(Date.now()-Z.t0)/1000);var r=Z.q.filter(function(k){return Z.ans[k]===AQ[k][3]}).length;Z.q.forEach(function(k){if(Z.ans[k]!=null)D.st[k]=Z.ans[k]===AQ[k][3]?1:0});D.mocks.push({at:Date.now(),r:r,n:Z.q.length,t:Z.t});save();render();window.scrollTo(0,0)};
